package dev.izlek.analytics.internal

import dev.izlek.analytics.InternalIzlekApi

/**
 * UUIDv7 generator (RFC 9562): 48-bit unix ms, 12-bit counter, 62 random bits.
 *
 * Ids generated by one instance are monotonic even when the wall clock stalls or steps back a
 * little; a large backward jump (> 10 s) is accepted as the new time base. Not thread-safe:
 * owned by the SDK's serial dispatcher.
 */
@InternalIzlekApi
public class IdGenerator(private val randomBytes: (Int) -> ByteArray) {
    private var lastMs = -1L
    private var counter = 0

    public fun uuid7(nowMs: Long): ByteArray {
        val rnd = randomBytes(10)
        var ms = if (nowMs < 0) 0 else nowMs
        if (ms > lastMs || ms < lastMs - 10_000) {
            // 11 random bits leave headroom for increments within the same millisecond.
            counter = ((rnd[0].toInt() and 0x07) shl 8) or (rnd[1].toInt() and 0xFF)
        } else {
            ms = lastMs
            counter++
            if (counter > 0xFFF) {
                ms++
                counter = 0
            }
        }
        lastMs = ms
        val out = ByteArray(16)
        out[0] = (ms ushr 40).toByte()
        out[1] = (ms ushr 32).toByte()
        out[2] = (ms ushr 24).toByte()
        out[3] = (ms ushr 16).toByte()
        out[4] = (ms ushr 8).toByte()
        out[5] = ms.toByte()
        out[6] = (0x70 or (counter ushr 8)).toByte()
        out[7] = counter.toByte()
        for (i in 8 until 16) out[i] = rnd[i - 6]
        out[8] = ((out[8].toInt() and 0x3F) or 0x80).toByte()
        return out
    }

    public companion object {
        /** `8-4-4-4-12` lowercase text form. */
        public fun format(uuid: ByteArray): String {
            val h = uuid.toHex()
            return h.substring(0, 8) + "-" + h.substring(8, 12) + "-" + h.substring(12, 16) + "-" +
                h.substring(16, 20) + "-" + h.substring(20)
        }

        /**
         * UUIDv8-shaped 128-bit digest of [text] (four murmur3_32 passes with different seeds).
         * Used where an id has to be derived deterministically from a name.
         */
        public fun uuid8(text: String): ByteArray {
            val data = text.encodeToByteArray()
            val out = ByteArray(16)
            for (i in 0 until 4) {
                val h = Murmur3.hash32(data, seed = 0x17E1EC00 + i)
                out[i * 4] = (h ushr 24).toByte()
                out[i * 4 + 1] = (h ushr 16).toByte()
                out[i * 4 + 2] = (h ushr 8).toByte()
                out[i * 4 + 3] = h.toByte()
            }
            out[6] = ((out[6].toInt() and 0x0F) or 0x80).toByte()
            out[8] = ((out[8].toInt() and 0x3F) or 0x80).toByte()
            return out
        }
    }
}
